/**
 * Pesos sazonais mensais.
 *
 * Não representam limites máximos.
 * Servem somente para criar meses com maior e menor entrada de leads.
 */
const PESOS_SAZONAIS_MES = {
  1: 0.78,
  2: 0.88,
  3: 1.12,
  4: 0.98,
  5: 1.06,
  6: 1.17,
  7: 0.91,
  8: 1.03,
  9: 1.15,
  10: 1.21,
  11: 1.07,
  12: 0.84
};

/**
 * ============================================================
 * FUNÇÕES UTILITÁRIAS
 * ============================================================
 */

/**
 * Gerador pseudoaleatório determinístico.
 *
 * A mesma seed produz novamente os mesmos registros.
 */
function criarGeradorAleatorio(seedInicial) {
  let seed = Number(seedInicial) || 2025;

  return function random() {
    seed |= 0;
    seed = (seed + 0x6D2B79F5) | 0;

    let resultado = Math.imul(seed ^ (seed >>> 15), 1 | seed);

    resultado =
      resultado +
      Math.imul(resultado ^ (resultado >>> 7), 61 | resultado) ^
      resultado;

    return ((resultado ^ (resultado >>> 14)) >>> 0) / 4294967296;
  };
}

function inteiroAleatorio(random, minimo, maximo) {
  return Math.floor(random() * (maximo - minimo + 1)) + minimo;
}

function decimalAleatorio(random, minimo, maximo, casas = 2) {
  const valor = random() * (maximo - minimo) + minimo;
  return Number(valor.toFixed(casas));
}

function escolherAleatorio(random, array) {
  if (!Array.isArray(array) || array.length === 0) {
    throw new Error('Tentativa de selecionar um item em uma lista vazia.');
  }

  return array[inteiroAleatorio(random, 0, array.length - 1)];
}

function escolherComPeso(random, opcoes) {
  if (!Array.isArray(opcoes) || opcoes.length === 0) {
    throw new Error('A lista ponderada está vazia.');
  }

  const total = opcoes.reduce(
    (soma, opcao) => soma + Number(opcao.peso || 0),
    0
  );

  if (total <= 0) {
    throw new Error('A lista ponderada não possui pesos válidos.');
  }

  let sorteio = random() * total;

  for (const opcao of opcoes) {
    sorteio -= Number(opcao.peso || 0);

    if (sorteio <= 0) {
      return opcao.valor;
    }
  }

  return opcoes[opcoes.length - 1].valor;
}

function normalizarTexto(valor) {
  return String(valor || '')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

function criarSlug(valor) {
  return normalizarTexto(valor)
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

function pad(numero, tamanho = 2) {
  return String(numero).padStart(tamanho, '0');
}

function formatarNumeroFinanceiro(valor) {
  return Number(Number(valor || 0).toFixed(2));
}

function menorData(dataA, dataB) {
  return dataA.getTime() <= dataB.getTime() ? dataA : dataB;
}

function maiorData(dataA, dataB) {
  return dataA.getTime() >= dataB.getTime() ? dataA : dataB;
}

function adicionarDias(data, quantidade) {
  const novaData = new Date(data.getTime());
  novaData.setUTCDate(novaData.getUTCDate() + quantidade);
  return novaData;
}

function dataAleatoriaEntre(random, inicio, termino) {
  const minimo = inicio.getTime();
  const maximo = termino.getTime();

  if (maximo < minimo) {
    throw new Error('O intervalo utilizado para gerar uma data é inválido.');
  }

  const timestamp = Math.floor(
    random() * (maximo - minimo + 1) + minimo
  );

  return new Date(timestamp);
}

/**
 * Aceita:
 *
 * 01/01/2025
 * 2025-01-01
 * 2025-01-01T10:00:00.000Z
 */
function converterData(valor, nomeCampo) {
  if (!valor) {
    throw new Error(`O campo "${nomeCampo}" não foi informado.`);
  }

  const texto = String(valor).trim();

  const formatoBR = /^(\d{2})\/(\d{2})\/(\d{4})$/;
  const correspondenciaBR = texto.match(formatoBR);

  if (correspondenciaBR) {
    const [, dia, mes, ano] = correspondenciaBR;

    const data = new Date(
      Date.UTC(
        Number(ano),
        Number(mes) - 1,
        Number(dia),
        0,
        0,
        0,
        0
      )
    );

    const dataValida =
      data.getUTCFullYear() === Number(ano) &&
      data.getUTCMonth() === Number(mes) - 1 &&
      data.getUTCDate() === Number(dia);

    if (!dataValida) {
      throw new Error(
        `A data "${texto}" do campo "${nomeCampo}" é inválida.`
      );
    }

    return data;
  }

  const formatoISO = /^\d{4}-\d{2}-\d{2}(?:T.*)?$/;

  if (!formatoISO.test(texto)) {
    throw new Error(
      `A data "${texto}" do campo "${nomeCampo}" possui formato inválido.`
    );
  }

  const data = new Date(texto);

  if (Number.isNaN(data.getTime())) {
    throw new Error(
      `A data "${texto}" do campo "${nomeCampo}" é inválida.`
    );
  }

  return data;
}

function inicioDoDia(data) {
  return new Date(
    Date.UTC(
      data.getUTCFullYear(),
      data.getUTCMonth(),
      data.getUTCDate(),
      0,
      0,
      0,
      0
    )
  );
}

function fimDoDia(data) {
  return new Date(
    Date.UTC(
      data.getUTCFullYear(),
      data.getUTCMonth(),
      data.getUTCDate(),
      23,
      59,
      59,
      999
    )
  );
}

/**
 * ============================================================
 * GERAÇÃO DE NOMES DE PESSOAS
 * ============================================================
 */

function criarNomePessoa(random) {
  const usarNomeComposto = random() < 0.28;

  const primeiroNome = usarNomeComposto
    ? escolherAleatorio(random, NOMES_COMPOSTOS)
    : escolherAleatorio(random, PRIMEIROS_NOMES);

  /**
   * Aproximadamente:
   *
   * 28% com primeiro nome + sobrenome.
   * 47% com primeiro nome + dois sobrenomes.
   * 25% com primeiro nome + nome intermediário + dois sobrenomes.
   *
   * Caso o primeiro nome já seja composto, o total de partes aumenta.
   */
  const formato = escolherComPeso(random, [
    {
      valor: 'curto',
      peso: 28
    },
    {
      valor: 'medio',
      peso: 47
    },
    {
      valor: 'longo',
      peso: 25
    }
  ]);

  const sobrenome1 = escolherAleatorio(
    random,
    SOBRENOMES
  );

  let sobrenome2 = escolherAleatorio(
    random,
    SOBRENOMES
  );

  while (sobrenome2 === sobrenome1) {
    sobrenome2 = escolherAleatorio(
      random,
      SOBRENOMES
    );
  }

  if (formato === 'curto') {
    return `${primeiroNome} ${sobrenome1}`;
  }

  if (formato === 'medio') {
    return `${primeiroNome} ${sobrenome1} ${sobrenome2}`;
  }

  const nomeIntermediario = escolherAleatorio(
    random,
    NOMES_INTERMEDIARIOS
  );

  return (
    `${primeiroNome} ` +
    `${nomeIntermediario} ` +
    `${sobrenome1} ` +
    `${sobrenome2}`
  );
}

/**
 * ============================================================
 * GERAÇÃO DE NOMES DE EMPRESAS
 * ============================================================
 */

function criarNomeEmpresaBase(random) {
  const formato = escolherComPeso(random, [
    {
      valor: 'simples',
      peso: 35
    },
    {
      valor: 'composta',
      peso: 42
    },
    {
      valor: 'institucional',
      peso: 23
    }
  ]);

  const prefixo = escolherAleatorio(
    random,
    PREFIXOS_EMPRESA
  );

  const segmento = escolherAleatorio(
    random,
    SEGMENTOS_EMPRESA
  );

  if (formato === 'simples') {
    return `${prefixo} ${segmento}`;
  }

  if (formato === 'composta') {
    const complemento = escolherAleatorio(
      random,
      COMPLEMENTOS_EMPRESA
    );

    return `${prefixo} ${segmento} ${complemento}`;
  }

  const prefixoInstitucional = escolherAleatorio(
    random,
    PREFIXOS_INSTITUCIONAIS_EMPRESA
  );

  const terminacao = escolherAleatorio(
    random,
    TERMINACOES_EMPRESA
  );

  return (
    `${prefixoInstitucional} ` +
    `${prefixo} ` +
    `${segmento} ` +
    `${terminacao}`
  );
}

/**
 * Garante nomes empresariais únicos.
 *
 * Caso ocorra repetição, um complemento numérico sintético será adicionado.
 */
function criarNomeEmpresaUnico(random, nomesUtilizados) {
  const nomeBase = criarNomeEmpresaBase(random);

  if (!nomesUtilizados.has(nomeBase)) {
    nomesUtilizados.add(nomeBase);
    return nomeBase;
  }

  let contador = 2;
  let nomeComComplemento = `${nomeBase} ${contador}`;

  while (nomesUtilizados.has(nomeComComplemento)) {
    contador += 1;
    nomeComComplemento = `${nomeBase} ${contador}`;
  }

  nomesUtilizados.add(nomeComComplemento);

  return nomeComComplemento;
}

/**
 * ============================================================
 * DADOS DE CONTATO FICTÍCIOS
 * ============================================================
 */

function criarTelefoneContato(indice) {
  /**
   * DDD 00 propositalmente inválido.
   */
  const numero = String(indice)
    .padStart(8, '0')
    .slice(-8);

  return `+55 00 9${numero.slice(0, 4)}-${numero.slice(4)}`;
}

function criarTelefoneEmpresa(indice) {
  /**
   * DDD 00 propositalmente inválido.
   */
  const numero = String(indice)
    .padStart(4, '0')
    .slice(-4);

  return `+55 00 3000-${numero}`;
}

/**
 * ============================================================
 * LOCALIZAÇÃO DA ESTRUTURA PRINCIPAL DO INPUT
 * ============================================================
 */

/**
 * Aceita:
 *
 * {
 *   "quantidade_de_leads": 6000,
 *   ...
 * }
 *
 * ou:
 *
 * {
 *   "Estrutura_de_teste": {
 *     "quantidade_de_leads": 6000,
 *     ...
 *   }
 * }
 */
function obterEstrutura(json) {
  if (!json || typeof json !== 'object' || Array.isArray(json)) {
    throw new Error(
      'O input recebido precisa ser um objeto JSON válido.'
    );
  }

  if (
    Object.prototype.hasOwnProperty.call(
      json,
      'quantidade_de_leads'
    ) ||
    Object.prototype.hasOwnProperty.call(
      json,
      'funis'
    ) ||
    Object.prototype.hasOwnProperty.call(
      json,
      'usuarios'
    )
  ) {
    return json;
  }

  for (const valor of Object.values(json)) {
    if (
      valor &&
      typeof valor === 'object' &&
      !Array.isArray(valor) &&
      (
        Object.prototype.hasOwnProperty.call(
          valor,
          'quantidade_de_leads'
        ) ||
        Object.prototype.hasOwnProperty.call(
          valor,
          'funis'
        ) ||
        Object.prototype.hasOwnProperty.call(
          valor,
          'usuarios'
        )
      )
    ) {
      return valor;
    }
  }

  throw new Error(
    'Não foi possível localizar a estrutura principal no input.'
  );
}

/**
 * ============================================================
 * LEITURA DINÂMICA DOS SERVIÇOS
 * ============================================================
 */

/**
 * Aceita:
 *
 * "servicos": [
 *   "Desenvolvimento Web",
 *   "Consultoria em TI"
 * ]
 *
 * ou:
 *
 * "servicos": [
 *   { "nome": "Desenvolvimento Web" },
 *   { "name": "Consultoria em TI" }
 * ]
 *
 * Também aceita:
 *
 * "campos_personalizados_lead": [
 *   {
 *     "name": "Serviços",
 *     "type": "select",
 *     "options": [...]
 *   }
 * ]
 */
function obterServicos(estrutura) {
  const listaDireta =
    estrutura.servicos ||
    estrutura['serviços'] ||
    estrutura.lista_de_servicos ||
    estrutura['lista_de_serviços'];

  if (Array.isArray(listaDireta)) {
    const servicos = listaDireta
      .map((servico) => {
        if (typeof servico === 'string') {
          return servico.trim();
        }

        if (servico && typeof servico === 'object') {
          return String(
            servico.nome ||
            servico.name ||
            servico.value ||
            ''
          ).trim();
        }

        return '';
      })
      .filter(Boolean);

    if (servicos.length > 0) {
      return [...new Set(servicos)];
    }
  }

  const camposLead = Array.isArray(
    estrutura.campos_personalizados_lead
  )
    ? estrutura.campos_personalizados_lead
    : [];

  const campoServicos = camposLead.find((campo) => {
    const nomeCampo = normalizarTexto(
      campo.name ||
      campo.nome
    );

    return (
      nomeCampo === 'servicos' ||
      nomeCampo === 'servico'
    );
  });

  if (campoServicos) {
    const opcoes =
      campoServicos.options ||
      campoServicos.enums ||
      campoServicos.opcoes ||
      [];

    const servicos = opcoes
      .map((opcao) => {
        if (typeof opcao === 'string') {
          return opcao.trim();
        }

        if (opcao && typeof opcao === 'object') {
          return String(
            opcao.nome ||
            opcao.name ||
            opcao.value ||
            ''
          ).trim();
        }

        return '';
      })
      .filter(Boolean);

    if (servicos.length > 0) {
      return [...new Set(servicos)];
    }
  }

  throw new Error(
    'Nenhum serviço foi encontrado. Informe a propriedade "servicos" no input.'
  );
}

/**
 * ============================================================
 * DISTRIBUIÇÃO SAZONAL DOS LEADS
 * ============================================================
 */

function obterMesesEntreDatas(dataInicio, dataTermino) {
  const meses = [];

  let cursor = new Date(
    Date.UTC(
      dataInicio.getUTCFullYear(),
      dataInicio.getUTCMonth(),
      1
    )
  );

  const limite = new Date(
    Date.UTC(
      dataTermino.getUTCFullYear(),
      dataTermino.getUTCMonth(),
      1
    )
  );

  while (cursor.getTime() <= limite.getTime()) {
    const inicioMes = new Date(
      Date.UTC(
        cursor.getUTCFullYear(),
        cursor.getUTCMonth(),
        1,
        0,
        0,
        0,
        0
      )
    );

    const fimMes = new Date(
      Date.UTC(
        cursor.getUTCFullYear(),
        cursor.getUTCMonth() + 1,
        0,
        23,
        59,
        59,
        999
      )
    );

    meses.push({
      ano: cursor.getUTCFullYear(),
      mes: cursor.getUTCMonth() + 1,
      inicio: maiorData(inicioMes, dataInicio),
      termino: menorData(fimMes, dataTermino)
    });

    cursor = new Date(
      Date.UTC(
        cursor.getUTCFullYear(),
        cursor.getUTCMonth() + 1,
        1
      )
    );
  }

  return meses;
}

function distribuirQuantidadePorMes(
  random,
  quantidade,
  meses
) {
  const mesesComPeso = meses.map((mes) => {
    const pesoBase =
      PESOS_SAZONAIS_MES[mes.mes] || 1;

    /**
     * Variação adicional para evitar uma distribuição mecânica.
     */
    const variacao = decimalAleatorio(
      random,
      0.88,
      1.12,
      4
    );

    return {
      ...mes,
      peso: pesoBase * variacao
    };
  });

  const somaPesos = mesesComPeso.reduce(
    (soma, mes) => soma + mes.peso,
    0
  );

  const distribuicao = mesesComPeso.map((mes) => {
    const quantidadeExata =
      quantidade * (mes.peso / somaPesos);

    const quantidadeInicial =
      Math.floor(quantidadeExata);

    return {
      ...mes,
      quantidade: quantidadeInicial,
      fracao: quantidadeExata - quantidadeInicial
    };
  });

  const quantidadeDistribuida =
    distribuicao.reduce(
      (soma, mes) => soma + mes.quantidade,
      0
    );

  let restante =
    quantidade - quantidadeDistribuida;

  distribuicao
    .sort((a, b) => b.fracao - a.fracao)
    .forEach((mes) => {
      if (restante > 0) {
        mes.quantidade += 1;
        restante -= 1;
      }
    });

  return distribuicao.sort((a, b) => {
    if (a.ano !== b.ano) {
      return a.ano - b.ano;
    }

    return a.mes - b.mes;
  });
}

/**
 * ============================================================
 * CLASSIFICAÇÃO DAS ETAPAS
 * ============================================================
 */

function obterPesoEtapa(nomeEtapa) {
  const nome = normalizarTexto(nomeEtapa);

  if (nome.includes('incoming')) return 10;
  if (nome.includes('novo lead qualificado')) return 13;
  if (nome.includes('novo lead')) return 16;
  if (nome.includes('contato inicial')) return 15;
  if (nome.includes('qualificacao em andamento')) return 14;
  if (nome === 'qualificado') return 11;
  if (nome.includes('desqualificado')) return 8;
  if (nome.includes('contato de vendas')) return 12;
  if (nome.includes('proposta')) return 10;
  if (nome.includes('negociacao')) return 8;
  if (nome.includes('closed - won')) return 7;
  if (nome.includes('closed - lost')) return 9;

  return 5;
}

function etapaEhGanha(nomeEtapa) {
  const nome = normalizarTexto(nomeEtapa);

  return (
    nome.includes('closed - won') ||
    nome.includes('fechado - ganhou') ||
    nome.includes('fechado ganho') ||
    nome === 'ganho' ||
    nome === 'ganhou'
  );
}

function etapaEhDesqualificada(nomeEtapa) {
  const nome = normalizarTexto(nomeEtapa);

  return nome.includes('desqualificado');
}

function etapaEhPerdida(nomeEtapa) {
  const nome = normalizarTexto(nomeEtapa);

  return (
    etapaEhDesqualificada(nomeEtapa) ||
    nome.includes('closed - lost') ||
    nome.includes('fechado - perdido') ||
    nome.includes('fechado perdido') ||
    nome === 'perdido'
  );
}

function etapaEhPropostaOuNegociacao(nomeEtapa) {
  const nome = normalizarTexto(nomeEtapa);

  return (
    nome.includes('proposta') ||
    nome.includes('negociacao')
  );
}

/**
 * Define os indicadores comerciais do lead.
 */
function classificarEtapaComercial(
  random,
  nomeEtapa
) {
  const vendaRealizada =
    etapaEhGanha(nomeEtapa);

  const leadPerdido =
    etapaEhPerdida(nomeEtapa);

  const desqualificado =
    etapaEhDesqualificada(nomeEtapa);

  const propostaOuNegociacao =
    etapaEhPropostaOuNegociacao(nomeEtapa);

  if (vendaRealizada) {
    return {
      proposta_gerada: true,
      possui_valor_comercial: true,
      venda_realizada: true,
      lead_perdido: false
    };
  }

  if (propostaOuNegociacao) {
    return {
      proposta_gerada: true,
      possui_valor_comercial: true,
      venda_realizada: false,
      lead_perdido: false
    };
  }

  if (desqualificado) {
    return {
      proposta_gerada: false,
      possui_valor_comercial: false,
      venda_realizada: false,
      lead_perdido: true
    };
  }

  if (leadPerdido) {
    /**
     * Parte das oportunidades perdidas recebeu proposta
     * antes do encerramento.
     */
    const propostaGerada = random() < 0.7;

    return {
      proposta_gerada: propostaGerada,
      possui_valor_comercial: propostaGerada,
      venda_realizada: false,
      lead_perdido: true
    };
  }

  return {
    proposta_gerada: false,
    possui_valor_comercial: false,
    venda_realizada: false,
    lead_perdido: false
  };
}

/**
 * ============================================================
 * UTMS
 * ============================================================
 */

function gerarUtm(random, servico, criadoEm) {
  const trimestre =
    Math.floor(criadoEm.getUTCMonth() / 3) + 1;

  const ano =
    criadoEm.getUTCFullYear();

  const servicoSlug =
    criarSlug(servico);

  const plataforma = escolherComPeso(random, [
    {
      valor: 'meta',
      peso: 58
    },
    {
      valor: 'google',
      peso: 42
    }
  ]);

  if (plataforma === 'meta') {
    const source = escolherComPeso(random, [
      {
        valor: 'instagram',
        peso: 62
      },
      {
        valor: 'facebook',
        peso: 38
      }
    ]);

    return {
      utm_source: source,
      utm_campaing:
        `meta_${servicoSlug}_q${trimestre}_${ano}`,
      utm_medium: 'paid_social',
      utm_content: escolherAleatorio(random, [
        'carrossel_case',
        'video_demonstracao',
        'imagem_beneficio',
        'remarketing_visitantes',
        'formulario_leads'
      ])
    };
  }

  return {
    utm_source: 'google',
    utm_campaing:
      `google_${servicoSlug}_q${trimestre}_${ano}`,
    utm_medium: 'cpc',
    utm_content: escolherAleatorio(random, [
      'pesquisa_servico',
      'pesquisa_orcamento',
      'pesquisa_empresa',
      'display_remarketing',
      'performance_max'
    ])
  };
}

/**
 * ============================================================
 * PROCESSAMENTO PRINCIPAL
 * ============================================================
 */

const resultados = [];

for (const inputItem of inputItems) {
  const estrutura =
    obterEstrutura(inputItem.json);

  const quantidade = Number(
    estrutura.quantidade_de_leads
  );

  const seed = Number(
    estrutura.seed ?? 2025
  );

  const valorMinimoVenda = Number(
    estrutura.valor_minimo_venda ?? 2500
  );

  const valorMaximoVenda = Number(
    estrutura.valor_maximo_venda ?? 120000
  );

  if (
    !Number.isInteger(quantidade) ||
    quantidade <= 0
  ) {
    throw new Error(
      'O campo "quantidade_de_leads" precisa ser um número inteiro maior que zero.'
    );
  }

  if (quantidade > 100000) {
    throw new Error(
      'A quantidade solicitada excede o limite de 100000 registros por execução.'
    );
  }

  if (
    !Number.isFinite(valorMinimoVenda) ||
    valorMinimoVenda < 0
  ) {
    throw new Error(
      'O campo "valor_minimo_venda" precisa ser maior ou igual a zero.'
    );
  }

  if (
    !Number.isFinite(valorMaximoVenda) ||
    valorMaximoVenda <= 0
  ) {
    throw new Error(
      'O campo "valor_maximo_venda" precisa ser maior que zero.'
    );
  }

  if (valorMaximoVenda < valorMinimoVenda) {
    throw new Error(
      'O valor máximo da venda precisa ser maior ou igual ao valor mínimo.'
    );
  }

  const dataInicio = inicioDoDia(
    converterData(
      estrutura.data_inicio,
      'data_inicio'
    )
  );

  const dataTermino = fimDoDia(
    converterData(
      estrutura.data_termino,
      'data_termino'
    )
  );

  if (dataTermino.getTime() < dataInicio.getTime()) {
    throw new Error(
      'A data de término precisa ser maior ou igual à data de início.'
    );
  }

  const funis = Array.isArray(
    estrutura.funis
  )
    ? estrutura.funis
    : [];

  const etapas = Array.isArray(
    estrutura.etapas
  )
    ? estrutura.etapas
    : [];

  const usuarios = Array.isArray(
    estrutura.usuarios
  )
    ? estrutura.usuarios
    : [];

  const servicos =
    obterServicos(estrutura);

  if (funis.length === 0) {
    throw new Error(
      'Nenhum funil foi recebido no campo "funis".'
    );
  }

  if (etapas.length === 0) {
    throw new Error(
      'Nenhuma etapa foi recebida no campo "etapas".'
    );
  }

  if (usuarios.length === 0) {
    throw new Error(
      'Nenhum usuário foi recebido no campo "usuarios".'
    );
  }

  const random =
    criarGeradorAleatorio(seed);

  const meses =
    obterMesesEntreDatas(
      dataInicio,
      dataTermino
    );

  const distribuicaoMensal =
    distribuirQuantidadePorMes(
      random,
      quantidade,
      meses
    );

  /**
   * Cerca de 72% dos leads terão empresas distintas.
   *
   * Algumas empresas poderão aparecer em mais de um lead,
   * simulando recorrência ou novas demandas.
   */
  const quantidadeEmpresas = Math.max(
    1,
    Math.ceil(quantidade * 0.72)
  );

  const empresas = [];
  const nomesEmpresasUtilizados = new Set();

  for (
    let indice = 1;
    indice <= quantidadeEmpresas;
    indice++
  ) {
    empresas.push({
      empresa_id_simulado:
        `EMP-${pad(indice, 6)}`,

      nome:
        criarNomeEmpresaUnico(
          random,
          nomesEmpresasUtilizados
        ),

      telefone:
        criarTelefoneEmpresa(indice),

      email:
        `empresa${pad(indice, 6)}@exemplo.invalid`,

      ltv: 0,

      data_ultimo_contrato: null,

      criado_em: null,

      atualizado_em: null
    });
  }

  /**
   * Gera datas de criação respeitando a sazonalidade mensal.
   */
  const datasCriacao = [];

  for (const mes of distribuicaoMensal) {
    for (
      let indice = 0;
      indice < mes.quantidade;
      indice++
    ) {
      datasCriacao.push(
        dataAleatoriaEntre(
          random,
          mes.inicio,
          mes.termino
        )
      );
    }
  }

  datasCriacao.sort(
    (a, b) =>
      a.getTime() - b.getTime()
  );

  /**
   * Registros temporários necessários para calcular
   * o LTV final das empresas.
   */
  const registrosTemporarios = [];

  for (
    let indice = 0;
    indice < quantidade;
    indice++
  ) {
    const numeroSequencial =
      indice + 1;

    const criadoEm =
      datasCriacao[indice];

    const limiteAtualizacao = menorData(
      adicionarDias(
        criadoEm,
        inteiroAleatorio(
          random,
          1,
          90
        )
      ),
      dataTermino
    );

    const atualizadoEm =
      dataAleatoriaEntre(
        random,
        criadoEm,
        limiteAtualizacao
      );

    /**
     * Algumas empresas recebem mais de um lead.
     */
    const indiceEmpresa =
      Math.floor(
        Math.pow(random(), 1.35) *
        empresas.length
      );

    const empresa = empresas[
      Math.min(
        indiceEmpresa,
        empresas.length - 1
      )
    ];

    const contatoNome =
      criarNomePessoa(random);

    const cargo =
      escolherAleatorio(
        random,
        CARGOS
      );

    const servico =
      escolherAleatorio(
        random,
        servicos
      );

    const usuario =
      escolherAleatorio(
        random,
        usuarios
      );

    const funil =
      escolherAleatorio(
        random,
        funis
      );

    const etapasDoFunil =
      etapas.filter(
        (etapa) =>
          String(etapa.funil_id) ===
          String(funil.id)
      );

    if (etapasDoFunil.length === 0) {
      throw new Error(
        `Nenhuma etapa foi encontrada para o funil "${funil.nome}".`
      );
    }

    const etapa =
      escolherComPeso(
        random,
        etapasDoFunil.map(
          (item) => ({
            valor: item,
            peso: obterPesoEtapa(
              item.nome
            )
          })
        )
      );

    const classificacao =
      classificarEtapaComercial(
        random,
        etapa.nome
      );

    /**
     * O valor representa o potencial comercial da oportunidade.
     *
     * Pode existir em:
     *
     * - propostas enviadas;
     * - negociações;
     * - vendas ganhas;
     * - parte das oportunidades perdidas.
     */
    const valorVenda =
      classificacao.possui_valor_comercial
        ? decimalAleatorio(
            random,
            valorMinimoVenda,
            valorMaximoVenda,
            2
          )
        : 0;

    /**
     * A data do contrato somente existe para vendas ganhas.
     */
    const dataContrato =
      classificacao.venda_realizada
        ? dataAleatoriaEntre(
            random,
            criadoEm,
            atualizadoEm
          )
        : null;

    const utm =
      gerarUtm(
        random,
        servico,
        criadoEm
      );

    if (
      !empresa.criado_em ||
      criadoEm < empresa.criado_em
    ) {
      empresa.criado_em = criadoEm;
    }

    if (
      !empresa.atualizado_em ||
      atualizadoEm > empresa.atualizado_em
    ) {
      empresa.atualizado_em =
        atualizadoEm;
    }

    /**
     * LTV considera exclusivamente contratos ganhos.
     */
    if (
      classificacao.venda_realizada
    ) {
      empresa.ltv +=
        valorVenda;

      if (
        !empresa.data_ultimo_contrato ||
        dataContrato >
          empresa.data_ultimo_contrato
      ) {
        empresa.data_ultimo_contrato =
          dataContrato;
      }
    }

    registrosTemporarios.push({
      numeroSequencial,
      criadoEm,
      atualizadoEm,
      dataContrato,
      classificacao,
      valorVenda,
      empresa,
      contatoNome,
      cargo,
      servico,
      usuario,
      funil,
      etapa,
      utm
    });
  }

  /**
   * Monta o retorno final após o cálculo definitivo do LTV.
   */
  for (
    const registro
    of registrosTemporarios
  ) {
    const {
      numeroSequencial,
      criadoEm,
      atualizadoEm,
      dataContrato,
      classificacao,
      valorVenda,
      empresa,
      contatoNome,
      cargo,
      servico,
      usuario,
      funil,
      etapa,
      utm
    } = registro;

    resultados.push({
      json: {
        lead: {
          lead_id_simulado:
            `LEAD-${pad(
              numeroSequencial,
              6
            )}`,

          nome:
            `Projeto ${servico} - ${empresa.nome}`,

          funil_id:
            String(
              funil.id || ''
            ),

          funil_id_externo:
            String(
              funil.id_externo || ''
            ),

          funil_name:
            String(
              funil.nome || ''
            ),

          etapa_id:
            String(
              etapa.id || ''
            ),

          etapa_id_externo:
            String(
              etapa.id_externo || ''
            ),

          etapa_name:
            String(
              etapa.nome || ''
            ),

          /**
           * Valor potencial ou realizado da oportunidade.
           */
          venda:
            formatarNumeroFinanceiro(
              valorVenda
            ),

          /**
           * true somente quando houve fechamento ganho.
           */
          venda_realizada:
            classificacao.venda_realizada,

          /**
           * true quando a oportunidade recebeu uma proposta.
           */
          proposta_gerada:
            classificacao.proposta_gerada,

          /**
           * true para perdas e desqualificações.
           */
          lead_perdido:
            classificacao.lead_perdido,

          usuario_responsavel_id:
            String(
              usuario.id || ''
            ),

          usuario_responsavel_id_externo:
            String(
              usuario.id_externo || ''
            ),

          usuario_responsavel:
            String(
              usuario.nome || ''
            ),

          usuario_responsavel_papel:
            String(
              usuario.papel || ''
            ),

          utm_source:
            utm.utm_source,

          /**
           * Mantido como "utm_campaing" para respeitar
           * a estrutura originalmente solicitada.
           *
           * A grafia convencional é "utm_campaign".
           */
          utm_campaing:
            utm.utm_campaing,

          utm_medium:
            utm.utm_medium,

          utm_content:
            utm.utm_content,

          servicos:
            servico,

          data_contrato:
            dataContrato
              ? dataContrato.toISOString()
              : null,

          criado_em:
            criadoEm.toISOString(),

          atualizado_em:
            atualizadoEm.toISOString(),

          mes_referencia:
            `${criadoEm.getUTCFullYear()}-${pad(
              criadoEm.getUTCMonth() + 1
            )}`
        },

        contato: {
          contato_id_simulado:
            `CON-${pad(
              numeroSequencial,
              6
            )}`,

          nome:
            contatoNome,

          telefone:
            criarTelefoneContato(
              numeroSequencial
            ),

          email:
            `contato${pad(
              numeroSequencial,
              6
            )}@exemplo.invalid`,

          cargo,

          criado_em:
            criadoEm.toISOString(),

          atualizado_em:
            atualizadoEm.toISOString()
        },

        empresa: {
          empresa_id_simulado:
            empresa.empresa_id_simulado,

          nome:
            empresa.nome,

          telefone:
            empresa.telefone,

          email:
            empresa.email,

          /**
           * LTV considera somente contratos efetivamente ganhos.
           */
          ltv:
            formatarNumeroFinanceiro(
              empresa.ltv
            ),

          data_ultimo_contrato:
            empresa.data_ultimo_contrato
              ? empresa.data_ultimo_contrato.toISOString()
              : null,

          criado_em:
            empresa.criado_em
              ? empresa.criado_em.toISOString()
              : criadoEm.toISOString(),

          atualizado_em:
            empresa.atualizado_em
              ? empresa.atualizado_em.toISOString()
              : atualizadoEm.toISOString()
        }
      }
    });
  }
}

return resultados;

