function obterConfiguracaoGeral() {
  let itensMerge = [];

  try {
    itensMerge = $('Merge').all();
  } catch (erro) {
    itensMerge = [];
  }

  const configuracao = itensMerge
    .map((item) => item?.json ?? item)
    .find((json) => json && typeof json === 'object' && !Array.isArray(json));

  if (!configuracao) {
    throw new Error('Não foi possível localizar os dados de configuração no node "Merge".');
  }

  return configuracao;
}

function normalizarEmpresas(itens) {
  return itens
    .flatMap((item) => {
      const json = item?.json ?? item;
      return Array.isArray(json) ? json : [json];
    })
    .map((empresa) => empresa?.json ?? empresa)
    .filter((empresa) => empresa && typeof empresa === 'object' && !Array.isArray(empresa));
}

function validarEmpresaParaVinculo(empresa, indiceContato) {
  if (!valorPreenchido(empresa.id)) {
    throw new Error(`A empresa selecionada para o contato ${indiceContato} não possui "id" do banco.`);
  }

  if (!valorPreenchido(empresa.id_externo)) {
    throw new Error(
      `A empresa "${empresa.nome || empresa.id}" selecionada para o contato ${indiceContato} não possui "id_externo" da Kommo.`
    );
  }

  const idExterno = Number(empresa.id_externo);

  if (!Number.isInteger(idExterno) || idExterno <= 0) {
    throw new Error(
