function criarGeradorAleatorio(seedInicial) {
  let seed = Number(seedInicial) || 2025;

  return function random() {
    seed |= 0;
    seed = (seed + 0x6D2B79F5) | 0;

    let resultado = Math.imul(seed ^ (seed >>> 15), 1 | seed);

    resultado =
      resultado +
      Math.imul(resultado ^ (resultado >>> 7), 61 | resultado) ^
      resultado;

    return ((resultado ^ (resultado >>> 14)) >>> 0) / 4294967296;
