function escolherComPeso(random, opcoes) {
  const total = opcoes.reduce(
    (soma, opcao) => soma + Number(opcao.peso || 0),
    0
  );

  let sorteio = random() * total;

  for (const opcao of opcoes) {
    sorteio -= Number(opcao.peso || 0);

    if (sorteio <= 0) {
      return opcao.valor;
    }
  }

  return opcoes[opcoes.length - 1].valor;
}

