    body.push(criarBodyEmpresaKommo(empresa, estrutura, camposEmpresa));
  }

  const lotesBody = dividirEmLotes(body, LIMITE_EMPRESAS_POR_BODY);
  const lotesEmpresas = dividirEmLotes(empresas, LIMITE_EMPRESAS_POR_BODY);

  for (let indiceLote = 0; indiceLote < lotesBody.length; indiceLote++) {
