/**
 * Localiza e consolida a configuração recebida pelo node Merge.
 */
function obterConfiguracaoGeral() {
  let itensMerge = [];

  try {
    itensMerge = $('Merge').all();
  } catch (erro) {
    itensMerge = [];
  }

  const itensJson = itensMerge
    .flatMap((item) => {
      const json = item?.json ?? item;

      return Array.isArray(json)
        ? json
        : [json];
    })
    .map((json) => json?.json ?? json)
    .filter(
      (json) =>
        json &&
        typeof json === 'object' &&
        !Array.isArray(json)
    );

  const configuracao = consolidarConfiguracaoMerge(itensJson);

  if (!configuracao) {
    throw new Error(
      'Não foi possível localizar os dados de configuração no node "Merge".'
    );
  }

  return configuracao;
}

/**
 * Consolida os diferentes itens retornados pelo node Merge.
 */
function consolidarConfiguracaoMerge(itensJson) {
  if (itensJson.length === 0) {
    return null;
  }

  const configuracao = {
    funis: [],
    etapas: [],
    usuarios: [],
    servicos: [],
    campos_lead: []
  };

  for (const json of itensJson) {
    mesclarCamposEscalares(configuracao, json);

    adicionarLista(configuracao.funis, json.funis);
    adicionarLista(configuracao.etapas, json.etapas);
    adicionarLista(configuracao.usuarios, json.usuarios);
    adicionarLista(configuracao.servicos, json.servicos);

    adicionarLista(
      configuracao.campos_lead,
      extrairCamposLead(json)
    );

    if (pareceCampoPersonalizadoLead(json)) {
      configuracao.campos_lead.push(json);
    }
  }

  configuracao.funis = removerDuplicadosPorChave(
    configuracao.funis,
    ['id_externo', 'id', 'nome']
  );

  configuracao.etapas = removerDuplicadosPorChave(
    configuracao.etapas,
    ['funil_id_externo', 'id_externo', 'id', 'nome']
  );

  configuracao.usuarios = removerDuplicadosPorChave(
    configuracao.usuarios,
    ['id_externo', 'id', 'nome']
  );

  configuracao.servicos = [
    ...new Set(
      configuracao.servicos
        .map((servico) => String(servico).trim())
        .filter(Boolean)
    )
  ];

  configuracao.campos_lead = removerDuplicadosPorChave(
    configuracao.campos_lead,
    [
      'id',
      'field_id',
      'code',
      'field_code',
      'name',
      'nome'
    ]
  );

  return configuracao;
}

/**
 * Mescla campos simples de configuração.
 */
function mesclarCamposEscalares(destino, origem) {
  const chavesEscalares = [
    'quantidade_de_leads',
    'quantidade_de_empresas',
    'quantidade_de_contatos',
    'data_inicio',
    'data_termino',
    'seed',
    'kommo_subdomain',
    'token',
    'responsible_user_id',
    'usuario_responsavel_id',
    'responsavel_id',
    'created_by',
    'criado_por',
    'updated_by',
    'atualizado_por'
  ];

  for (const chave of chavesEscalares) {
    if (valorPreenchido(origem[chave])) {
      destino[chave] = origem[chave];
    }
  }
}

/**
 * Adiciona elementos de uma lista ao array de destino.
 */
function adicionarLista(destino, valor) {
  if (!Array.isArray(valor)) {
    return;
  }

  for (const item of valor) {
    const normalizado = item?.json ?? item;

    if (
      normalizado !== undefined &&
      normalizado !== null
    ) {
      destino.push(normalizado);
    }
  }
}

/**
 * Extrai campos personalizados de leads das possíveis estruturas.
 */
function extrairCamposLead(json) {
  const campos = [];

  adicionarLista(campos, json.lead_fields);
  adicionarLista(campos, json.campos_lead);
  adicionarLista(campos, json.campos_personalizados_lead);
  adicionarLista(campos, json.campos_kommo_lead);
  adicionarLista(campos, json.custom_fields_lead);
  adicionarLista(campos, json.custom_fields);
  adicionarLista(campos, json.campos);
  adicionarLista(campos, json.campos_disponiveis);
  adicionarLista(campos, json.campos_disponíveis);
  adicionarLista(campos, json.fields);
  adicionarLista(campos, json._embedded?.custom_fields);

  return campos.filter(pareceCampoPersonalizadoLead);
}

/**
 * Verifica se o objeto possui estrutura semelhante
 * a um campo personalizado da Kommo.
 */
function pareceCampoPersonalizadoLead(valor) {
  if (
    !valor ||
    typeof valor !== 'object' ||
    Array.isArray(valor)
  ) {
    return false;
  }

  const temIdentificadorCampo =
    valorPreenchido(valor.field_id) ||
    valorPreenchido(valor.field_code) ||
    valorPreenchido(valor.id) ||
    valorPreenchido(valor.code);

  const temNomeCampo =
    valorPreenchido(valor.name) ||
    valorPreenchido(valor.nome);

  const pareceCampoKommo =
    valorPreenchido(valor.type) ||
    valorPreenchido(valor.field_type) ||
    valorPreenchido(valor.enums) ||
    valorPreenchido(valor.sort);

  return (
    temIdentificadorCampo &&
    temNomeCampo &&
    pareceCampoKommo
  );
}

/**
 * Remove duplicados com base em uma combinação de chaves.
 */
function removerDuplicadosPorChave(lista, chaves) {
  const resultado = [];
  const vistos = new Set();

  for (const item of lista) {
    if (
      item === undefined ||
      item === null
    ) {
      continue;
    }

    if (typeof item !== 'object') {
      const chavePrimitiva = String(item);

      if (!vistos.has(chavePrimitiva)) {
        vistos.add(chavePrimitiva);
        resultado.push(item);
      }

      continue;
    }

    const chave = chaves
      .map((nomeChave) =>
        String(item[nomeChave] ?? '').trim()
      )
      .filter(Boolean)
      .join('|');

    const chaveFinal = chave || JSON.stringify(item);

    if (!vistos.has(chaveFinal)) {
      vistos.add(chaveFinal);
      resultado.push(item);
    }
  }

  return resultado;
}

/**
 * Normaliza contatos recebidos pelo input principal.
 */
function normalizarContatos(itens) {
  return itens
    .flatMap((item) => {
      const json = item?.json ?? item;

      return Array.isArray(json)
        ? json
        : [json];
    })
    .map((contato) => contato?.json ?? contato)
    .filter(
      (contato) =>
        contato &&
        typeof contato === 'object' &&
        !Array.isArray(contato)
    );
}

/**
 * Normaliza listas de entidades.
 */
function normalizarEntidades(valor, nomeCampo) {
  if (!Array.isArray(valor)) {
    throw new Error(
      `O campo "${nomeCampo}" precisa ser uma lista no node Merge.`
    );
  }

  return valor
    .map((item) => item?.json ?? item)
    .filter(
      (item) =>
        item &&
        typeof item === 'object' &&
        !Array.isArray(item)
    );
}

/**
 * Normaliza listas simples de texto.
 */
function normalizarListaTexto(valor) {
  if (!Array.isArray(valor)) {
    return [];
  }

  return valor
    .map((item) => String(item || '').trim())
    .filter(Boolean);
}

/**
 * Valida se o contato possui os IDs necessários.
 */
function validarContatoParaVinculo(contato, indiceLead) {
  if (!valorPreenchido(contato.id)) {
    throw new Error(
      `O contato selecionado para o lead ${indiceLead} não possui "id" do banco.`
    );
  }

  if (!valorPreenchido(contato.id_externo)) {
    throw new Error(
      `O contato "${contato.nome || contato.id}" selecionado para o lead ${indiceLead} não possui "id_externo" da Kommo.`
    );
  }

  if (!valorPreenchido(contato.empresa_id_externo)) {
    throw new Error(
      `O contato "${contato.nome || contato.id}" selecionado para o lead ${indiceLead} não possui "empresa_id_externo" da Kommo.`
    );
  }

  validarIdExternoNumerico(
    contato.id_externo,
    `contato "${contato.nome || contato.id}"`
  );

  validarIdExternoNumerico(
    contato.empresa_id_externo,
    `empresa do contato "${contato.nome || contato.id}"`
  );
}

/**
 * Valida IDs externos utilizados nos vínculos da Kommo.
 */
function validarIdExternoNumerico(valor, contexto) {
  const id = Number(valor);

  if (
    !Number.isInteger(id) ||
    id <= 0
  ) {
    throw new Error(
      `O id externo da ${contexto} é inválido para vínculo na Kommo.`
    );
  }
}

/**
 * Seleciona contatos de maneira sequencial inicialmente.
 * Caso existam mais leads do que contatos, seleciona aleatoriamente.
 */
function escolherContatoParaLead(
  random,
  listaContatos,
  indice
) {
  if (indice <= listaContatos.length) {
    return listaContatos[indice - 1];
  }

  return listaContatos[
    Math.floor(random() * listaContatos.length)
  ];
}

/**
 * Seleciona funil, etapa e usuário.
 */
function escolherFunilEtapaUsuario(
  random,
  funis,
  etapas,
  usuarios
) {
  const funil = escolherFunil(random, funis);

  const etapasDoFunil = etapas
    .filter(
      (etapa) =>
        String(etapa.funil_id_externo || '') ===
        String(funil.id_externo || '')
    )
    .filter(etapaPermitidaParaCriacaoLead)
    .sort(
      (a, b) =>
        Number(a.ordem || 0) -
        Number(b.ordem || 0)
    );

  if (etapasDoFunil.length === 0) {
    throw new Error(
      `Nenhuma etapa válida para criação de lead foi encontrada no funil "${funil.nome}".`
    );
  }

  const etapa = escolherEtapa(random, etapasDoFunil);

  const usuario = escolherUsuarioResponsavel(
    random,
    usuarios,
    funil,
    etapa
  );

  validarIdExternoNumerico(
    etapa.funil_id_externo,
    `funil externo da etapa "${etapa.nome}"`
  );

  validarIdExternoNumerico(
    etapa.id_externo,
    `etapa "${etapa.nome}"`
  );

  validarIdExternoNumerico(
    usuario.id_externo,
    `usuário "${usuario.nome}"`
  );

  return {
    funil,
    etapa,
    usuario
  };
}

/**
 * Impede criação em etapas internas não permitidas.
 */
function etapaPermitidaParaCriacaoLead(etapa) {
  const idExterno = String(
    etapa.id_externo || ''
  ).trim();

  const nome = normalizarTexto(etapa.nome);

  if (idExterno === '143') {
    return false;
  }

  if (nome.includes('closed - lost')) {
    return false;
  }

  if (nome.includes('incoming leads')) {
    return false;
  }

  return true;
}

/**
 * Identifica a etapa padrao de ganho da Kommo ou uma etapa
 * equivalente nomeada em portugues/ingles.
 */
function etapaRepresentaLeadGanho(etapa) {
  const idExterno = String(
    etapa?.id_externo || ''
  ).trim();

  const nome = normalizarTexto(etapa?.nome);

  return (
    idExterno === '142' ||
    nome.includes('closed - won') ||
    nome.includes('fechado - ganho') ||
    nome.includes('venda ganha') ||
    nome === 'ganho'
  );
}

/**
 * Prioriza os funis de vendas e qualificação.
 */
function escolherFunil(random, funis) {
  const vendas = funis.find((funil) =>
    normalizarTexto(funil.nome).includes('vendas')
  );

  const qualificacao = funis.find((funil) =>
    normalizarTexto(funil.nome).includes('qualificacao')
  );

  if (vendas && qualificacao) {
    return random() < 0.58
      ? vendas
      : qualificacao;
  }

  return escolherAleatorio(random, funis);
}

/**
 * Seleciona uma etapa com base em peso.
 */
function escolherEtapa(random, etapasDoFunil) {
  const opcoes = etapasDoFunil.map((etapa) => ({
    valor: etapa,
    peso: pesoEtapa(etapa)
  }));

  return escolherComPeso(random, opcoes);
}

/**
 * Define pesos para as etapas.
 */
function pesoEtapa(etapa) {
  const nome = normalizarTexto(etapa.nome);

  if (etapaRepresentaLeadGanho(etapa)) {
    return 12;
  }

  if (
    nome.includes('closed - lost') ||
    nome.includes('desqualificado')
  ) {
    return 10;
  }

  if (nome.includes('negociacao')) {
    return 14;
  }

  if (nome.includes('proposta')) {
    return 16;
  }

  if (nome.includes('qualificado')) {
    return 18;
  }

  if (nome.includes('andamento')) {
    return 16;
  }

  if (nome.includes('contato')) {
    return 18;
  }

  if (nome.includes('novo')) {
    return 20;
  }

  if (nome.includes('incoming')) {
    return 8;
  }

  return 10;
}

/**
 * Prioriza closers ou SDRs com base no contexto do lead.
 */
function escolherUsuarioResponsavel(
  random,
  usuarios,
  funil,
  etapa
) {
  const nomeFunil = normalizarTexto(funil.nome);
  const nomeEtapa = normalizarTexto(etapa.nome);

  const preferirCloser =
    nomeFunil.includes('vendas') ||
    nomeEtapa.includes('proposta') ||
    nomeEtapa.includes('negociacao') ||
    etapaRepresentaLeadGanho(etapa);

  const papelPreferido = preferirCloser
    ? 'closer'
    : 'sdr';

  const usuariosPreferidos = usuarios.filter(
    (usuario) =>
      normalizarTexto(usuario.papel) === papelPreferido
  );

  if (usuariosPreferidos.length > 0) {
    return escolherAleatorio(
      random,
      usuariosPreferidos
    );
  }

  return escolherAleatorio(random, usuarios);
}

/**
 * Monta o objeto local utilizado na geração do payload.
 */
function criarLeadLocal(
  indice,
  contato,
  contextoFunil,
  servico,
  venda,
  utm,
  dataContrato,
  criadoEm,
  atualizadoEm
) {
  return {
    indice_simulado: indice,
    lead_id_simulado: `LEA-${pad(indice, 6)}`,
    id_externo: '',

    contato_id: String(contato.id),
    contato_id_externo: String(contato.id_externo),
    contato_nome: contato.nome || '',

    empresa_id_externo: String(
      contato.empresa_id_externo
    ),

    etapa_id_externo: String(
      contextoFunil.etapa.id_externo
    ),

    etapa_nome: contextoFunil.etapa.nome || '',

    funil_id_externo: String(
      contextoFunil.etapa.funil_id_externo
    ),

    funil_nome: contextoFunil.funil.nome || '',

    usuario_responsavel_id_externo: String(
      contextoFunil.usuario.id_externo
    ),

    usuario_responsavel_nome:
      contextoFunil.usuario.nome || '',

    nome: `${servico} - ${contato.nome || `Contato ${indice}`}`,

    venda,

    utm_source: utm.source,
    utm_campaing: utm.campaign,
    utm_medium: utm.medium,
    utm_content: utm.content,
    utm_term: utm.term,
    utm_referrer: utm.utmReferrer,

    referrer: utm.referrer,
    gclientid: utm.gclientid,
    gclid: utm.gclid,
    fbclid: utm.fbclid,

    servicos: servico,

    criado_em: criadoEm.toISOString(),

    atualizado_em: atualizadoEm.toISOString(),

    ...(dataContrato
      ? {
          data_contrato:
            dataContrato.toISOString()
        }
      : {})
  };
}

/**
 * Monta o payload enviado para a API da Kommo.
 */
function criarBodyLeadKommo(lead, camposLead) {
  const customFieldsValues = [];

  adicionarCampoPersonalizado(
    customFieldsValues,
    camposLead.utmSource,
    lead.utm_source
  );

  adicionarCampoPersonalizado(
    customFieldsValues,
    camposLead.utmCampaign,
    lead.utm_campaing
  );

  adicionarCampoPersonalizado(
    customFieldsValues,
    camposLead.utmMedium,
    lead.utm_medium
  );

  adicionarCampoPersonalizado(
    customFieldsValues,
    camposLead.utmContent,
    lead.utm_content
  );

  adicionarCampoPersonalizado(
    customFieldsValues,
    camposLead.utmTerm,
    lead.utm_term
  );

  adicionarCampoPersonalizado(
    customFieldsValues,
    camposLead.utmReferrer,
    lead.utm_referrer
  );

  adicionarCampoPersonalizado(
    customFieldsValues,
    camposLead.referrer,
    lead.referrer
  );

  adicionarCampoPersonalizado(
    customFieldsValues,
    camposLead.gclientid,
    lead.gclientid
  );

  adicionarCampoPersonalizado(
    customFieldsValues,
    camposLead.gclid,
    lead.gclid
  );

  adicionarCampoPersonalizado(
    customFieldsValues,
    camposLead.fbclid,
    lead.fbclid
  );

  adicionarCampoPersonalizado(
    customFieldsValues,
    camposLead.servicos,
    lead.servicos
  );

  /*
   * O valor enviado para Data do Contrato é convertido
   * para Unix timestamp exatamente como updated_at.
   */
  if (lead.data_contrato) {
    adicionarCampoPersonalizado(
      customFieldsValues,
      camposLead.dataContrato,
      unixSegundos(lead.data_contrato)
    );
  }

  const bodyLead = {
    request_id: String(
      Number(lead.indice_simulado)
    ),

    name: lead.nome,

    price: Number(lead.venda),

    pipeline_id: Number(
      lead.funil_id_externo
    ),

    status_id: Number(
      lead.etapa_id_externo
    ),

    responsible_user_id: Number(
      lead.usuario_responsavel_id_externo
    ),

    created_at: unixSegundos(
      lead.criado_em
    ),

    updated_at: unixSegundos(
      lead.atualizado_em
    ),

    _embedded: {
      contacts: [
        {
          id: Number(
            lead.contato_id_externo
          ),
          is_main: true
        }
      ],

      companies: [
        {
          id: Number(
            lead.empresa_id_externo
          )
        }
      ]
    }
  };

  if (customFieldsValues.length > 0) {
    bodyLead.custom_fields_values =
      customFieldsValues;
  }

  return bodyLead;
}

/**
 * Localiza os campos personalizados pelo nome, ID ou código.
 */
function obterConfiguracaoCamposLead(configuracao) {
  const origem =
    configuracao.campos_lead ||
    configuracao.campos_personalizados_lead ||
    configuracao.campos_kommo_lead ||
    configuracao.custom_fields_lead ||
    null;

  if (Array.isArray(origem)) {
    return {
      utmSource: encontrarCampoEmLista(
        origem,
        [
          'utm source',
          'utm_source',
          'utm-source',
          'origem utm'
        ]
      ),

      utmCampaign: encontrarCampoEmLista(
        origem,
        [
          'utm campaign',
          'utm campaing',
          'utm_campaing',
          'utm_campaign',
          'campanha utm'
        ]
      ),

      utmMedium: encontrarCampoEmLista(
        origem,
        [
          'utm medium',
          'utm_medium',
          'utm-medium',
          'midia utm',
          'mídia utm'
        ]
      ),

      utmContent: encontrarCampoEmLista(
        origem,
        [
          'utm content',
          'utm_content',
          'utm-content',
          'conteudo utm',
          'conteúdo utm'
        ]
      ),

      utmTerm: encontrarCampoEmLista(
        origem,
        [
          'utm term',
          'utm_term',
          'utm-term',
          'termo utm'
        ]
      ),

      utmReferrer: encontrarCampoEmLista(
        origem,
        [
          'utm referrer',
          'utm_referrer',
          'utm-referrer'
        ]
      ),

      referrer: encontrarCampoEmLista(
        origem,
        [
          'referrer',
          'referer',
          'referenciador'
        ]
      ),

      gclientid: encontrarCampoEmLista(
        origem,
        [
          'gclientid',
          'gclient id',
          'google client id'
        ]
      ),

      gclid: encontrarCampoEmLista(
        origem,
        ['gclid']
      ),

      fbclid: encontrarCampoEmLista(
        origem,
        ['fbclid']
      ),

      servicos: encontrarCampoEmLista(
        origem,
        [
          'servicos',
          'serviços',
          'servios',
          'servi?os',
          'servico',
          'serviço',
          'servio',
          'servi?o',
          'service',
          'services'
        ]
      ),

      dataContrato: encontrarCampoEmLista(
        origem,
        [
          'data contrato',
          'data_contrato',
          'contrato',
          'contract date'
        ]
      )
    };
  }

  if (
    !origem ||
    typeof origem !== 'object'
  ) {
    return {
      utmSource: null,
      utmCampaign: null,
      utmMedium: null,
      utmContent: null,
      utmTerm: null,
      utmReferrer: null,
      referrer: null,
      gclientid: null,
      gclid: null,
      fbclid: null,
      servicos: null,
      dataContrato: null
    };
  }

  return {
    utmSource: campoPorIdOuCodigo(
      origem.utm_source ||
      origem.utmSource ||
      origem.utm_source_field_id
    ),

    utmCampaign: campoPorIdOuCodigo(
      origem.utm_campaing ||
      origem.utm_campaign ||
      origem.utmCampaign ||
      origem.utm_campaign_field_id
    ),

    utmMedium: campoPorIdOuCodigo(
      origem.utm_medium ||
      origem.utmMedium ||
      origem.utm_medium_field_id
    ),

    utmContent: campoPorIdOuCodigo(
      origem.utm_content ||
      origem.utmContent ||
      origem.utm_content_field_id
    ),

    utmTerm: campoPorIdOuCodigo(
      origem.utm_term ||
      origem.utmTerm ||
      origem.utm_term_field_id
    ),

    utmReferrer: campoPorIdOuCodigo(
      origem.utm_referrer ||
      origem.utmReferrer ||
      origem.utm_referrer_field_id
    ),

    referrer: campoPorIdOuCodigo(
      origem.referrer ||
      origem.referer ||
      origem.referrer_field_id
    ),

    gclientid: campoPorIdOuCodigo(
      origem.gclientid ||
      origem.gclientId ||
      origem.gclientid_field_id
    ),

    gclid: campoPorIdOuCodigo(
      origem.gclid ||
      origem.gclid_field_id
    ),

    fbclid: campoPorIdOuCodigo(
      origem.fbclid ||
      origem.fbclid_field_id
    ),

    servicos: campoPorIdOuCodigo(
      origem.servicos ||
      origem.serviços ||
      origem.servico ||
      origem.serviço
    ),

    dataContrato: campoPorIdOuCodigo(
      origem.data_contrato ||
      origem.dataContrato ||
      origem.data_contrato_field_id
    )
  };
}

/**
 * Procura um campo em uma lista utilizando nomes possíveis.
 */
function encontrarCampoEmLista(
  campos,
  nomesPossiveis
) {
  const nomesNormalizados =
    nomesPossiveis.map(normalizarTexto);

  for (const campo of campos) {
    const identificadoresCampo =
      obterIdentificadoresCampoNormalizados(campo);

    if (
      identificadoresCampo.some(
        (identificador) =>
          nomesNormalizados.includes(
            identificador
          )
      )
    ) {
      return normalizarConfiguracaoCampo(campo);
    }
  }

  for (const campo of campos) {
    const identificadoresCampo =
      obterIdentificadoresCampoNormalizados(campo);

    const bateComNome =
      identificadoresCampo.some(
        (identificador) =>
          nomesNormalizados.some(
            (nomePossivel) =>
              identificador.includes(
                nomePossivel
              ) ||
              nomePossivel.includes(
                identificador
              )
          )
      );

    if (bateComNome) {
      return normalizarConfiguracaoCampo(campo);
    }
  }

  return null;
}

/**
 * Retorna possíveis nomes e códigos normalizados.
 */
function obterIdentificadoresCampoNormalizados(
  campo
) {
  return [
    campo.name,
    campo.nome,
    campo.code,
    campo.codigo,
    campo.field_code,
    campo.field_name
  ]
    .map(normalizarTexto)
    .filter(Boolean);
}

/**
 * Normaliza um campo recebido por ID ou código.
 */
function campoPorIdOuCodigo(valor) {
  const campo = valorOuNulo(valor);

  if (campo === null) {
    return null;
  }

  if (typeof campo === 'object') {
    return normalizarConfiguracaoCampo(campo);
  }

  const texto = String(campo).trim();

  if (/^\d+$/.test(texto)) {
    return {
      field_id: Number(texto)
    };
  }

  return {
    field_code: texto
  };
}

/**
 * Adiciona um campo personalizado ao payload.
 */
function adicionarCampoPersonalizado(
  campos,
  campo,
  valor
) {
  if (
    !campo ||
    valor === undefined ||
    valor === null ||
    valor === ''
  ) {
    return;
  }

  const identificadorCampo =
    criarIdentificadorCampoKommo(campo);

  const valores =
    criarValoresCampoPersonalizado(
      campo,
      valor
    );

  if (
    !identificadorCampo ||
    valores.length === 0
  ) {
    return;
  }

  campos.push({
    ...identificadorCampo,
    values: valores
  });
}

/**
 * Normaliza a configuração de um campo da Kommo.
 */
function normalizarConfiguracaoCampo(campo) {
  if (
    !campo ||
    typeof campo !== 'object' ||
    Array.isArray(campo)
  ) {
    return null;
  }

  const fieldId =
    valorOuNulo(campo.field_id) ??
    valorOuNulo(campo.id);

  const fieldCode =
    valorOuNulo(campo.field_code) ??
    valorOuNulo(campo.code);

  const configuracao = {};

  if (fieldId !== null) {
    const id = Number(fieldId);

    if (
      Number.isInteger(id) &&
      id > 0
    ) {
      configuracao.field_id = id;
    }
  } else if (fieldCode !== null) {
    configuracao.field_code =
      String(fieldCode).trim();
  }

  if (
    !configuracao.field_id &&
    !configuracao.field_code
  ) {
    return null;
  }

  configuracao.name = String(
    campo.name ||
    campo.nome ||
    campo.field_name ||
    ''
  ).trim();

  configuracao.type = String(
    campo.type ||
    campo.field_type ||
    ''
  ).trim();

  configuracao.enums =
    Array.isArray(campo.enums)
      ? campo.enums
      : [];

  return configuracao;
}

/**
 * Retorna o identificador aceito pela API da Kommo.
 */
function criarIdentificadorCampoKommo(campo) {
  if (
    valorOuNulo(campo.field_id) !== null
  ) {
    return {
      field_id: Number(campo.field_id)
    };
  }

  if (
    valorOuNulo(campo.field_code) !== null
  ) {
    return {
      field_code: String(campo.field_code)
    };
  }

  return null;
}

/**
 * Cria a lista de valores do campo personalizado.
 */
function criarValoresCampoPersonalizado(
  campo,
  valor
) {
  if (Array.isArray(valor)) {
    return valor.flatMap((item) =>
      criarValoresCampoPersonalizado(
        campo,
        item
      )
    );
  }

  const tipoCampo = normalizarTexto(
    campo.type
  );

  if (
    [
      'select',
      'radiobutton',
      'category'
    ].includes(tipoCampo)
  ) {
    const enumEncontrado =
      encontrarEnumCampo(
        campo.enums,
        valor
      );

    if (!enumEncontrado) {
      const nomeCampo =
        campo.name ||
        campo.field_code ||
        campo.field_id ||
        'campo personalizado';

      throw new Error(
        `O valor "${valor}" não existe nos enums do campo de lead "${nomeCampo}".`
      );
    }

    return [
      {
        value: String(
          enumEncontrado.value
        ),
        enum_id: Number(
          enumEncontrado.id
        )
      }
    ];
  }

  if (tipoCampo === 'multiselect') {
    const enumEncontrado =
      encontrarEnumCampo(
        campo.enums,
        valor
      );

    if (!enumEncontrado) {
      const nomeCampo =
        campo.name ||
        campo.field_code ||
        campo.field_id ||
        'campo personalizado';

      throw new Error(
        `O valor "${valor}" não existe nos enums do campo de lead "${nomeCampo}".`
      );
    }

    return [
      {
        value: String(
          enumEncontrado.value
        ),
        enum_id: Number(
          enumEncontrado.id
        )
      }
    ];
  }

  return [
    {
      value: valor
    }
  ];
}

/**
 * Localiza um valor em uma lista de enums.
 */
function encontrarEnumCampo(enums, valor) {
  if (
    !Array.isArray(enums) ||
    enums.length === 0
  ) {
    return null;
  }

  const valorNormalizado =
    normalizarTexto(valor);

  return (
    enums.find(
      (item) =>
        normalizarTexto(item.value) ===
        valorNormalizado
    ) ||
    null
  );
}

/**
 * Calcula o valor simulado de venda.
 */
function calcularValorVenda(
  random,
  servico,
  etapa
) {
  const nomeServico =
    normalizarTexto(servico);

  let minimo = 1800;
  let maximo = 12000;

  if (nomeServico.includes('mobile')) {
    minimo = 9000;
    maximo = 45000;
  } else if (
    nomeServico.includes('api') ||
    nomeServico.includes('integracao')
  ) {
    minimo = 7000;
    maximo = 36000;
  } else if (nomeServico.includes('web')) {
    minimo = 4500;
    maximo = 28000;
  } else if (
    nomeServico.includes('consultoria')
  ) {
    minimo = 3500;
    maximo = 22000;
  } else if (
    nomeServico.includes('suporte')
  ) {
    minimo = 1200;
    maximo = 9000;
  }

  const multiplicador =
    etapaRepresentaLeadGanho(etapa)
      ? 1.15
      : 1;

  const valor = Math.round(
    (
      minimo +
      random() * (maximo - minimo)
    ) *
    multiplicador
  );

  return Math.max(0, valor);
}

/**
 * Gera informações simuladas de UTM.
 */
function criarUtm(random, servico) {
  const source = escolherAleatorio(
    random,
    UTM_SOURCES
  );

  const medium =
    source === 'organic'
      ? 'organic'
      : escolherAleatorio(
          random,
          UTM_MEDIUMS
        );

  const content = escolherAleatorio(
    random,
    UTM_CONTENTS
  );

  const campanhaBase = escolherAleatorio(
    random,
    CAMPANHAS
  );

  const campanhaServico = criarSlug(
    servico
  ).replace(/-/g, '_');

  const referrer =
    criarReferrerPorOrigem(source);

  return {
    source,
    medium,
    content,

    campaign:
      `${campanhaBase}-${campanhaServico}`,

    term: campanhaServico,

    utmReferrer: referrer,

    referrer,

    gclientid:
      `GA1.1.${inteiroAleatorio(
        random,
        100000000,
        999999999
      )}.${inteiroAleatorio(
        random,
        1700000000,
        1799999999
      )}`,

    gclid:
      source === 'google'
        ? `gclid_${inteiroAleatorio(
            random,
            1000000000,
            9999999999
          )}`
        : null,

    fbclid:
      [
        'facebook',
        'instagram'
      ].includes(source)
        ? `fbclid_${inteiroAleatorio(
            random,
            1000000000,
            9999999999
          )}`
        : null
  };
}

/**
 * Cria o referrer com base na origem.
 */
function criarReferrerPorOrigem(source) {
  const origem =
    normalizarTexto(source);

  if (origem === 'google') {
    return 'https://www.google.com/';
  }

  if (origem === 'facebook') {
    return 'https://www.facebook.com/';
  }

  if (origem === 'instagram') {
    return 'https://www.instagram.com/';
  }

  if (origem === 'linkedin') {
    return 'https://www.linkedin.com/';
  }

  if (origem === 'email') {
    return 'mailto:campanha@example.com';
  }

  return 'https://site.example.com/';
}

/**
 * Gera número inteiro aleatório.
 */
function inteiroAleatorio(
  random,
  minimo,
  maximo
) {
  return Math.floor(
    minimo +
    random() *
      (maximo - minimo + 1)
  );
}

/**
 * Calcula a menor data possível para criação do lead.
 */
function obterDataMinimaLead(
  contato,
  dataInicio,
  dataTermino
) {
  const criadoContato =
    converterDataOpcional(
      contato.criado_em
    );

  if (
    !criadoContato ||
    criadoContato.getTime() <
      dataInicio.getTime()
  ) {
    return dataInicio;
  }

  if (
    criadoContato.getTime() >
    dataTermino.getTime()
  ) {
    return dataInicio;
  }

  return criadoContato;
}

/**
 * Cria gerador pseudoaleatório determinístico.
 */
function criarGeradorAleatorio(
  seedInicial
) {
  let seed = Number(seedInicial) || 2025;

  return function random() {
    seed |= 0;

    seed =
      (seed + 0x6D2B79F5) |
      0;

    let resultado = Math.imul(
      seed ^ (seed >>> 15),
      1 | seed
    );

    resultado =
      (
        resultado +
        Math.imul(
          resultado ^
            (resultado >>> 7),
          61 | resultado
        )
      ) ^
      resultado;

    return (
      (
        resultado ^
        (resultado >>> 14)
      ) >>>
      0
    ) / 4294967296;
  };
}

/**
 * Seleciona item aleatório.
 */
function escolherAleatorio(
  random,
  array
) {
  if (
    !Array.isArray(array) ||
    array.length === 0
  ) {
    throw new Error(
      'Tentativa de selecionar um item em uma lista vazia.'
    );
  }

  return array[
    Math.floor(random() * array.length)
  ];
}

/**
 * Seleciona uma opção considerando pesos.
 */
function escolherComPeso(
  random,
  opcoes
) {
  const total = opcoes.reduce(
    (soma, opcao) =>
      soma +
      Number(opcao.peso || 0),
    0
  );

  let sorteio = random() * total;

  for (const opcao of opcoes) {
    sorteio -= Number(
      opcao.peso || 0
    );

    if (sorteio <= 0) {
      return opcao.valor;
    }
  }

  return opcoes[
    opcoes.length - 1
  ].valor;
}

/**
 * Preenche número com zeros à esquerda.
 */
function pad(numero, tamanho = 2) {
  return String(numero).padStart(
    tamanho,
    '0'
  );
}

/**
 * Normaliza textos para comparações.
 */
function normalizarTexto(valor) {
  return String(valor || '')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(
      /[\u0300-\u036f]/g,
      ''
    );
}

/**
 * Cria slug a partir de texto.
 */
function criarSlug(valor) {
  return normalizarTexto(valor)
    .replace(
      /[^a-z0-9]+/g,
      '-'
    )
    .replace(
      /^-+|-+$/g,
      ''
    );
}

/**
 * Verifica se valor foi preenchido.
 */
function valorPreenchido(valor) {
  return (
    valor !== undefined &&
    valor !== null &&
    String(valor).trim() !== ''
  );
}

/**
 * Retorna null para valores vazios.
 */
function valorOuNulo(valor) {
  if (
    valor === undefined ||
    valor === null ||
    valor === ''
  ) {
    return null;
  }

  return valor;
}

/**
 * Converte uma data obrigatória.
 */
function converterData(
  valor,
  nomeCampo
) {
  if (!valor) {
    throw new Error(
      `O campo "${nomeCampo}" não foi informado.`
    );
  }

  const data =
    converterDataOpcional(valor);

  if (!data) {
    throw new Error(
      `A data "${valor}" do campo "${nomeCampo}" é inválida.`
    );
  }

  return data;
}

/**
 * Converte uma data opcional.
 */
function converterDataOpcional(valor) {
  if (!valor) {
    return null;
  }

  const texto =
    String(valor).trim();

  const formatoBR =
    /^(\d{2})\/(\d{2})\/(\d{4})$/;

  const matchBR =
    texto.match(formatoBR);

  if (matchBR) {
    const [
      ,
      dia,
      mes,
      ano
    ] = matchBR;

    const data = new Date(
      Date.UTC(
        Number(ano),
        Number(mes) - 1,
        Number(dia)
      )
    );

    const dataValida =
      data.getUTCFullYear() ===
        Number(ano) &&
      data.getUTCMonth() ===
        Number(mes) - 1 &&
      data.getUTCDate() ===
        Number(dia);

    return dataValida
      ? data
      : null;
  }

  const data = new Date(texto);

  return Number.isNaN(
    data.getTime()
  )
    ? null
    : data;
}

/**
 * Ajusta uma data para o início do dia em UTC.
 */
function inicioDoDia(data) {
  return new Date(
    Date.UTC(
      data.getUTCFullYear(),
      data.getUTCMonth(),
      data.getUTCDate(),
      0,
      0,
      0,
      0
    )
  );
}

/**
 * Ajusta uma data para o fim do dia em UTC.
 */
function fimDoDia(data) {
  return new Date(
    Date.UTC(
      data.getUTCFullYear(),
      data.getUTCMonth(),
      data.getUTCDate(),
      23,
      59,
      59,
      999
    )
  );
}

/**
 * Gera uma data aleatória em um intervalo.
 */
function dataAleatoriaEntre(
  random,
  inicio,
  termino
) {
  const minimo = inicio.getTime();
  const maximo = termino.getTime();

  if (maximo < minimo) {
    throw new Error(
      'O intervalo de datas é inválido.'
    );
  }

  const timestamp = Math.floor(
    random() *
      (maximo - minimo + 1) +
      minimo
  );

  return new Date(timestamp);
}

/**
 * Converte Date ou texto ISO para Unix timestamp em segundos.
 */
function unixSegundos(data) {
  if (!data) {
    return null;
  }

  const dataConvertida =
    data instanceof Date
      ? data
      : new Date(data);

  if (
    Number.isNaN(
      dataConvertida.getTime()
    )
  ) {
    return null;
  }

  return Math.floor(
    dataConvertida.getTime() /
      1000
  );
}

/**
 * Divide arrays em lotes.
 */
function dividirEmLotes(
  array,
  tamanhoLote
) {
  const lotes = [];

  for (
    let indice = 0;
    indice < array.length;
    indice += tamanhoLote
  ) {
    lotes.push(
      array.slice(
        indice,
        indice + tamanhoLote
      )
    );
  }

  return lotes;
}

const items = $input.all();

/**
 * ============================================================
 * CAMPOS PERSONALIZADOS CADASTRADOS NA KOMMO
 * ============================================================
 *
 * O node "Merge" precisa possuir:
 *
 * {
 *   "lead_fields": [...]
 * }
 *
 * Cada campo possui:
 *
 * - id
 * - name
 * - code
 * - type
 * - enums
 */
const leads_fields = $('Merge').first().json.lead_fields;

if (!Array.isArray(leads_fields)) {
  throw new Error(
    'A variável leads_fields não foi encontrada em $("Merge").first().json.lead_fields.'
  );
}

/**
 * ============================================================
 * FUNÇÕES UTILITÁRIAS
 * ============================================================
 */

function texto(valor) {
  return String(valor ?? '').trim();
}

function inteiroOuNull(valor) {
  const numero = Number(valor);

  return Number.isInteger(numero) && numero > 0
    ? numero
    : null;
}

function numeroOuZero(valor) {
  const numero = Number(valor);

  return Number.isFinite(numero)
    ? numero
    : 0;
}

function unixParaIso(valor) {
  const timestamp = Number(valor);

  if (!Number.isFinite(timestamp) || timestamp <= 0) {
    return null;
  }

  return new Date(timestamp * 1000).toISOString();
}

/**
 * Normaliza textos para comparação.
 *
 * Exemplos:
 *
 * "Serviços"          -> "servicos"
 * "Data do Contrato"  -> "data_do_contrato"
 * "UTM_SOURCE"        -> "utm_source"
 */
function normalizarChave(valor) {
  return String(valor ?? '')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '');
}

/**
 * Retorna o primeiro valor do campo personalizado.
 */
function obterPrimeiroValor(campo) {
  if (
    !campo ||
    !Array.isArray(campo.values) ||
    campo.values.length === 0
  ) {
    return null;
  }

  return campo.values[0]?.value ?? null;
}

/**
 * Retorna o enum_id do primeiro valor.
 *
 * Utilizado principalmente para campos do tipo select.
 */
function obterPrimeiroEnumId(campo) {
  if (
    !campo ||
    !Array.isArray(campo.values) ||
    campo.values.length === 0
  ) {
    return null;
  }

  return inteiroOuNull(
    campo.values[0]?.enum_id
  );
}

/**
 * Formata o valor considerando o tipo do campo cadastrado.
 */
function formatarValorPorTipo(valor, tipo) {
  if (
    valor === null ||
    valor === undefined ||
    valor === ''
  ) {
    return null;
  }

  if (
    tipo === 'numeric' ||
    tipo === 'price'
  ) {
    const numero = Number(valor);

    return Number.isFinite(numero)
      ? numero
      : valor;
  }

  if (tipo === 'checkbox') {
    return Boolean(valor);
  }

  if (
    tipo === 'date' ||
    tipo === 'date_time'
  ) {
    const numero = Number(valor);

    /**
     * Caso a API retorne timestamp em segundos.
     */
    if (
      Number.isFinite(numero) &&
      numero > 0
    ) {
      return new Date(
        numero * 1000
      ).toISOString();
    }

    /**
     * Caso a API retorne string ISO.
     */
    const data = new Date(valor);

    return Number.isNaN(data.getTime())
      ? valor
      : data.toISOString();
  }

  return valor;
}

/**
 * ============================================================
 * ÍNDICES DOS CAMPOS PERSONALIZADOS
 * ============================================================
 *
 * Permitem localizar campos por:
 *
 * - ID;
 * - code;
 * - nome.
 */

const fieldsPorId = new Map();
const fieldsPorCode = new Map();
const fieldsPorNome = new Map();

for (const field of leads_fields) {
  const id =
    inteiroOuNull(field.id);

  if (!id) {
    continue;
  }

  fieldsPorId.set(
    id,
    field
  );

  const code =
    normalizarChave(field.code);

  if (code) {
    fieldsPorCode.set(
      code,
      field
    );
  }

  const nome =
    normalizarChave(field.name);

  if (nome) {
    fieldsPorNome.set(
      nome,
      field
    );
  }
}

/**
 * Localiza a definição de um campo pelo code.
 */
function encontrarDefinicaoPorCode(code) {
  return (
    fieldsPorCode.get(
      normalizarChave(code)
    ) ||
    null
  );
}

/**
 * Localiza a definição de um campo pelo nome.
 */
function encontrarDefinicaoPorNome(nome) {
  return (
    fieldsPorNome.get(
      normalizarChave(nome)
    ) ||
    null
  );
}

/**
 * Localiza um valor recebido da Kommo por field_id.
 */
function encontrarValorCustomField(
  customFieldsValues,
  fieldId
) {
  const id =
    inteiroOuNull(fieldId);

  if (!id) {
    return null;
  }

  return (
    customFieldsValues.find(
      (campo) =>
        Number(campo.field_id) === id
    ) ||
    null
  );
}

/**
 * Busca o valor de um custom field pelo code.
 */
function obterCampoPorCode(
  customFieldsValues,
  code
) {
  const definicao =
    encontrarDefinicaoPorCode(code);

  if (!definicao) {
    return null;
  }

  return encontrarValorCustomField(
    customFieldsValues,
    definicao.id
  );
}

/**
 * Busca o valor de um custom field pelo nome.
 *
 * Necessário para campos personalizados manuais,
 * pois eles normalmente não possuem code.
 */
function obterCampoPorNome(
  customFieldsValues,
  nome
) {
  const definicao =
    encontrarDefinicaoPorNome(nome);

  if (!definicao) {
    return null;
  }

  return encontrarValorCustomField(
    customFieldsValues,
    definicao.id
  );
}

/**
 * ============================================================
 * CONVERSÃO GENÉRICA DOS CAMPOS PERSONALIZADOS
 * ============================================================
 */

/**
 * Cria um objeto com todos os custom fields indexados
 * por uma chave legível.
 *
 * Exemplos:
 *
 * {
 *   "utm_source": {
 *     "field_id": 2387742,
 *     "value": "google"
 *   },
 *   "servicos": {
 *     "field_id": 2400502,
 *     "value": "Desenvolvimento Web",
 *     "enum_id": 1785946
 *   }
 * }
 */
function criarCustomFieldsNormalizados(
  customFieldsValues
) {
  const resultado = {};

  for (const campoRecebido of customFieldsValues) {
    const fieldId =
      inteiroOuNull(
        campoRecebido.field_id
      );

    if (!fieldId) {
      continue;
    }

    const definicao =
      fieldsPorId.get(fieldId);

    const chaveBase =
      normalizarChave(
        definicao?.code ||
        definicao?.name ||
        `field_${fieldId}`
      );

    /**
     * Evita sobrescrever campos em caso de colisão de nomes.
     */
    const chave =
      resultado[chaveBase]
        ? `${chaveBase}_${fieldId}`
        : chaveBase;

    const primeiroValor =
      obterPrimeiroValor(
        campoRecebido
      );

    resultado[chave] = {
      field_id:
        fieldId,

      name:
        definicao?.name ||
        null,

      code:
        definicao?.code ||
        null,

      type:
        definicao?.type ||
        null,

      value:
        formatarValorPorTipo(
          primeiroValor,
          definicao?.type
        ),

      enum_id:
        obterPrimeiroEnumId(
          campoRecebido
        ),

      values:
        Array.isArray(
          campoRecebido.values
        )
          ? campoRecebido.values
          : []
    };
  }

  return resultado;
}

/**
 * Cria um objeto simplificado contendo apenas:
 *
 * chave: valor
 */
function criarCustomFieldsFlat(
  customFieldsNormalizados
) {
  return Object.fromEntries(
    Object.entries(
      customFieldsNormalizados
    ).map(
      ([chave, campo]) => [
        chave,
        campo.value
      ]
    )
  );
}

/**
 * ============================================================
 * PROCESSAMENTO DOS LEADS
 * ============================================================
 */

return items.map(
  (item, indice) => {
    const lead =
      item.json || {};

    const leadId =
      inteiroOuNull(
        lead.id
      );

    if (!leadId) {
      throw new Error(
        `Item ${indice + 1}: ID do lead não encontrado.`
      );
    }

    const customFieldsValues =
      Array.isArray(
        lead.custom_fields_values
      )
        ? lead.custom_fields_values
        : [];

    const contatoPrincipal =
      Array.isArray(
        lead?._embedded?.contacts
      )
        ? (
            lead._embedded.contacts.find(
              (contato) =>
                contato.is_main === true
            ) ||
            lead._embedded.contacts[0] ||
            null
          )
        : null;

    const empresaPrincipal =
      Array.isArray(
        lead?._embedded?.companies
      )
        ? (
            lead._embedded.companies[0] ||
            null
          )
        : null;

    /**
     * --------------------------------------------
     * Campos nativos de rastreamento
     * --------------------------------------------
     *
     * Localizados dinamicamente pelo code.
     */

    const campoUtmSource =
      obterCampoPorCode(
        customFieldsValues,
        'UTM_SOURCE'
      );

    const campoUtmCampaign =
      obterCampoPorCode(
        customFieldsValues,
        'UTM_CAMPAIGN'
      );

    const campoUtmMedium =
      obterCampoPorCode(
        customFieldsValues,
        'UTM_MEDIUM'
      );

    const campoUtmContent =
      obterCampoPorCode(
        customFieldsValues,
        'UTM_CONTENT'
      );

    const campoUtmTerm =
      obterCampoPorCode(
        customFieldsValues,
        'UTM_TERM'
      );

    const campoUtmReferrer =
      obterCampoPorCode(
        customFieldsValues,
        'UTM_REFERRER'
      );

    const campoReferrer =
      obterCampoPorCode(
        customFieldsValues,
        'REFERRER'
      );

    const campoGclientid =
      obterCampoPorCode(
        customFieldsValues,
        'GCLIENTID'
      );

    const campoGclid =
      obterCampoPorCode(
        customFieldsValues,
        'GCLID'
      );

    const campoFbclid =
      obterCampoPorCode(
        customFieldsValues,
        'FBCLID'
      );

    const campoTiktokAdId =
      obterCampoPorCode(
        customFieldsValues,
        'TIKTOK_AD_ID_TD'
      );

    const campoTiktokAdName =
      obterCampoPorCode(
        customFieldsValues,
        'TIKTOK_AD_NAME_TD'
      );

    /**
     * --------------------------------------------
     * Campos personalizados manuais
     * --------------------------------------------
     *
     * Localizados dinamicamente pelo nome.
     */

    const campoServicos =
      obterCampoPorNome(
        customFieldsValues,
        'Serviços'
      );

    const campoDataContrato =
      obterCampoPorNome(
        customFieldsValues,
        'Data do Contrato'
      );

    const definicaoDataContrato =
      encontrarDefinicaoPorNome(
        'Data do Contrato'
      );

    const customFieldsNormalizados =
      criarCustomFieldsNormalizados(
        customFieldsValues
      );

    /**
     * --------------------------------------------
     * Retorno final
     * --------------------------------------------
     */

    return {
      json: {
        lead_id_externo:
          leadId,

        request_id:
          texto(
            lead.request_id
          ) || null,

        nome:
          texto(
            lead.name
          ),

        valor:
          numeroOuZero(
            lead.price
          ),

        funil_id_externo:
          inteiroOuNull(
            lead.pipeline_id
          ),

        etapa_id_externo:
          inteiroOuNull(
            lead.status_id
          ),

        usuario_responsavel_id_externo:
          inteiroOuNull(
            lead.responsible_user_id
          ),

        contato_id_externo:
          contatoPrincipal
            ? inteiroOuNull(
                contatoPrincipal.id
              )
            : null,

        empresa_id_externo:
          empresaPrincipal
            ? inteiroOuNull(
                empresaPrincipal.id
              )
            : null,

        criado_em:
          unixParaIso(
            lead.created_at
          ),

        atualizado_em:
          unixParaIso(
            lead.updated_at
          ),

        url_kommo:
          texto(
            lead?._links?.self?.href
          ) || null,

        /**
         * ------------------------------------------
         * Campos personalizados conhecidos
         * ------------------------------------------
         */

        utm_source:
          obterPrimeiroValor(
            campoUtmSource
          ),

        utm_campaign:
          obterPrimeiroValor(
            campoUtmCampaign
          ),

        utm_medium:
          obterPrimeiroValor(
            campoUtmMedium
          ),

        utm_content:
          obterPrimeiroValor(
            campoUtmContent
          ),

        utm_term:
          obterPrimeiroValor(
            campoUtmTerm
          ),

        utm_referrer:
          obterPrimeiroValor(
            campoUtmReferrer
          ),

        referrer:
          obterPrimeiroValor(
            campoReferrer
          ),

        gclientid:
          obterPrimeiroValor(
            campoGclientid
          ),

        gclid:
          obterPrimeiroValor(
            campoGclid
          ),

        fbclid:
          obterPrimeiroValor(
            campoFbclid
          ),

        tiktok_ad_id:
          obterPrimeiroValor(
            campoTiktokAdId
          ),

        tiktok_ad_name:
          obterPrimeiroValor(
            campoTiktokAdName
          ),

        servico:
          obterPrimeiroValor(
            campoServicos
          ),

        servico_enum_id:
          obterPrimeiroEnumId(
            campoServicos
          ),

        data_contrato:
          formatarValorPorTipo(
            obterPrimeiroValor(
              campoDataContrato
            ),
            definicaoDataContrato?.type
          ),

        /**
         * ------------------------------------------
         * Todos os campos personalizados
         * ------------------------------------------
         *
         * Mantidos para auditoria e futuras análises.
         */

        custom_fields_values:
          customFieldsValues,

        custom_fields_normalizados:
          customFieldsNormalizados,

        custom_fields_flat:
          criarCustomFieldsFlat(
            customFieldsNormalizados
          )
      }
    };
  }
);
